import sys
import time
from copy import deepcopy
from functools import partial
from os import path

from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import LOGGER_PORT, PS_REGEXP, SERVER_HOST, SERVER_PORT, vm_host
from ta_logcollector.task import Task
from ta_logcollector.utils.common import execute_in_parallel, run_remote_cmd
from ta_logcollector.utils.proxy_client import send_hello_request
from ta_logcollector.utils.runner import set_verdict_based_on_host_response
from ta_logcollector.ver import __version__


class ServerStartupManager(object):
    """Manager for logcollector servers startup. It takes care of detection and launching servers on provided hosts"""

    def __init__(self, hosts):
        # type: (Dict[str, vm_host]) -> None
        """
        Init method for ServerStartupManager
        :param hosts: dictionary with hosts, where each host is vm_host namedtuple
        """
        self._hosts_to_start = {}
        self._hosts = hosts
        self.logger = get_net_logger(SERVER_HOST, LOGGER_PORT, "ServerStartupManager")

    def start(self):
        # type: () -> None
        """
        The only which should be called if this is not Unit test.
        Checks if servers are running on hosts and starts them if not
        :return: None
        """
        self._check_if_server_is_alive(self._hosts)
        self._hosts_to_start = {
            host: host_data for host, host_data in deepcopy(self._hosts).items() if host_data.alive is False
        }
        self._start_servers()

    def _start_servers(self):
        # type: () -> None
        """Disables firewall on MANY hosts, launches lc_servers and checks connectivity towards them"""
        tasks_list = []
        for host_name in self._hosts_to_start:
            task = Task(self._disable_firewall_and_start_server_and_check_if_running, host_name)
            tasks_list.append(task)
        execute_in_parallel(tasks_list)

    def _disable_firewall_and_start_server_and_check_if_running(self, host_name):
        # type: (str) -> None
        """
        Disables firewall on SINGLE host, launches lc_server and checks connectivity towards it
        :param host_name: Name of particular host within self.hosts
        """
        self._disable_firewall(host_name)
        self._start_lc_server(host_name)
        self._check_server_started(host_name)

    def _disable_firewall(self, host_name, timeout=10):
        # type: (str, float) -> None
        """
        Disable firewall at hosts - add a rule to accept tcp traffic on server and log port.
        :param host_name: name of host in hosts dict
        :param timeout: timeout to acquire ssh connection
        :return: None
        """
        host = self._hosts_to_start[host_name]
        try:
            out, err = run_remote_cmd(
                logger=self.logger,
                user=host.usr,
                host=host.addr,
                passwd=host.passwd,
                cmd="sudo /sbin/iptables -I INPUT -p tcp -i eth0 -m multiport"
                " --dports {},{} -j ACCEPT".format(SERVER_PORT, LOGGER_PORT),
                timeout=timeout,
            )
            self.logger.debug("{}: out: {} err: {}".format(host, out, err))
        except Exception as err:
            self.logger.exception(err)
            raise

    def _start_lc_server(self, host_name, timeout=10):
        # type: (str, float) -> None
        """
        Starts lc_server on remote host.
        :param host_name: name of host from hosts dictionary
        :param timeout: timeout to acquire ssh connection
        """
        host = self._hosts_to_start[host_name]
        try:
            cmd = "nohup {py_env}/bin/lc_server{py_ver} -l {srv_host} -p {log_port} >>$HOME/lc.log 2>&1"
            if path.isfile("{}/bin/activate".format(sys.exec_prefix)):
                cmd = (
                    'nohup bash -ce "source {py_env}/bin/activate; '
                    '{py_env}/bin/lc_server{py_ver} -l {srv_host} -p {log_port};" >>$HOME/lc.log 2>&1'
                )
            cmd = cmd.format(
                py_env=sys.exec_prefix, py_ver=sys.version_info[0], srv_host=SERVER_HOST, log_port=LOGGER_PORT
            )
            run_remote_cmd(
                logger=self.logger,
                user=host.usr,
                host=host.addr,
                passwd=host.passwd,
                cmd=cmd,
                run_in_bg=True,
                timeout=timeout,
            )
            self.logger.debug("lc_server{} start at {}".format(sys.version_info[0], host))
        except Exception as err:
            self.logger.exception(err)
            raise

    def _check_if_server_is_alive(self, hosts=None):
        # type: (Dict[str, vm_host]) -> list
        """
        Checks if servers are alive in parallel by sending 'hello request' to them and updating host status.
        :param hosts: dictionary with hosts, where each host is vm_host namedtuple
        :return: results from `hello requests`
        """
        tasks_list = []
        for host_name, host_data in hosts.items():
            task = Task(
                send_hello_request,
                self.logger,
                host_data.addr,
                fn_callback=(
                    partial(self._set_host_alive_status, host_name),
                    partial(set_verdict_based_on_host_response, self.logger, "hello", host_data.addr),
                ),
            )
            tasks_list.append(task)
        return execute_in_parallel(tasks_list)

    def _check_server_started(self, host_name):
        # type: (str) -> dict
        """
        Checks if lc_server started on host provided by host_name
        :param host_name: name of host from hosts dictionary
        :return: Answer from the host which was checked
        """
        for sleep_time in range(2, 6):
            time.sleep(sleep_time)
            results = self._check_if_server_is_alive(hosts={host_name: self._hosts[host_name]})
            if self._hosts[host_name].alive is True:
                return results[0]
        else:
            self.logger.error("Server on {} could not start!".format(self._hosts[host_name]))
            return {}

    def _kill_lc_server_if_necessary(self, response, host_name):
        # type: (dict, str) -> bool
        """
        Returns True if server is working on proper version, false otherwise.
        :param response: Message for `hello request` including lc_server version on which it was launched
        :param host_name: name of host in hosts dictionary upon which method is called
        :return: True if server is running on proper version, false otherwise
        """
        current_ver = response.get("version", "not running")
        if current_ver != __version__:
            self.logger.debug(
                "Reported version = {}. Actual version = {}. Need to restart.".format(current_ver, __version__)
            )
            self._kill_lc_server(host_name)
            return False
        return True

    def _set_host_alive_status(self, host_name, future):
        # type: (str, Future) -> None
        """
        Sets host status based on response from server. If server responded with correct version,
        then host is considered as alive. False otherwise. This is callback method for "_check_if_server_is_alive",
        therefore should not be called by itself.
        :param host_name: name of host in hosts dictionary upon which method is called
        :param future: Future object as this is callback method
        :return: None
        """
        response = future.result()
        is_alive = self._kill_lc_server_if_necessary(response, host_name)
        host = self._hosts[host_name]
        self._hosts[host_name] = vm_host(host.addr, host.usr, host.passwd, is_alive)

    def _kill_lc_server(self, host_name):
        # type: (str) -> None
        """
        Kill lc_server at selected host.

        :param host_name: name of host in hosts dictionary upon which method is called
        """
        host = self._hosts[host_name]
        pids = self._get_remote_lc_server_pid(host)
        self._kill_remote_lc_server(host, pids)

    def _get_remote_lc_server_pid(self, host):
        # type: (vm_host) -> List[int]
        ps_output = ""
        pid_list = []
        cmd = 'ps {} | grep {} "{}"'.format("-ef", "-iE", ".*lc_server.*")
        try:
            ps_output, sterr = run_remote_cmd(
                logger=self.logger,
                user=host.usr,
                host=host.addr,
                passwd=host.passwd,
                cmd=cmd,
                run_in_bg=False,
                timeout=10,
            )
            self.logger.debug("{} {}".format(cmd, host))
            self.logger.debug("{}".format(sterr))
        except Exception as err:
            self.logger.exception(err)

        for proc in PS_REGEXP.finditer(ps_output):
            if str(proc.group("CMD")).startswith(("/opt/", "python")):
                pid_list.append(int(proc))
        return pid_list

    def _kill_remote_lc_server(self, host, pids):
        # type: (vm_host, List[int]) -> None
        for pid in pids:
            cmd = "kill -9 {}".format(pid)
            try:
                stout, sterr = run_remote_cmd(
                    logger=self.logger,
                    user=host.usr,
                    host=host.addr,
                    passwd=host.passwd,
                    cmd=cmd,
                    run_in_bg=False,
                    timeout=10,
                )
                self.logger.debug("{} {}".format(cmd, host))
                self.logger.debug("{} {}".format(stout, sterr))
            except Exception as err:
                self.logger.exception(err)
